foreach($case in $plan.cases){$position=0;$definition=Resolve $case.definition;$arguments=$null;if($case.arguments -is [string]){if($null -eq $definition){$arguments=[type[]]::new(0)}else{$arguments=$definition.GetGenericArguments()}}elseif($null -ne $case.arguments){$arguments=[type[]]::new($case.arguments.Count);for($i=0;$i -lt $arguments.Length;$i++){if($null -ne $case.arguments[$i]){$arguments[$i]=Resolve $case.arguments[$i]}}};$saved=$null;if($null -ne $arguments){$saved=$arguments.Clone()};$type=$null;$errorName='none';$message=$null;$hResult=0;$param=$null;try{$type=Construct $case.mode $definition $arguments}catch{$errorValue=$_.Exception;while($errorValue -is [Reflection.TargetInvocationException] -or $errorValue -is [Management.Automation.MethodInvocationException]){$errorValue=$errorValue.InnerException};$errorName=$errorValue.GetType().FullName;$message=$errorValue.Message;$hResult=$errorValue.HResult;if($errorValue -is [ArgumentException]){$param=$errorValue.ParamName}};$constructors.Add([ordered]@{id=$case.id;position=[int]$position;valueUnits=(Units $(if($null -ne $type){$(if($type.IsSignatureType){'signature:'}else{'runtime:'})+$type.ToString()}else{$null}));exception=$errorName;messageUnits=(Units $message);hResult=$hResult;paramUnits=(Units $param)});if($null -eq $type -or -not $type.IsSignatureType){continue}
