ion))};'HashStable'{$type.GetHashCode() -eq $type.GetHashCode()};'IsAssignableFromNull'{$type.IsAssignableFrom($null)};'IsAssignableFromSelf'{$type.IsAssignableFrom($type)};'IsAssignableFromInt'{$type.IsAssignableFrom([int])};'IsAssignableToNull'{$type.IsAssignableTo($null)};'IsAssignableToSelf'{$type.IsAssignableTo($type)};'IsAssignableToObject'{$type.IsAssignableTo([object])};'IsInstanceNull'{$type.IsInstanceOfType($null)};'IsInstanceInt'{$type.IsInstanceOfType(0)};'IsEquivalentNull'{$type.IsEquivalentTo($null)};'IsEquivalentSelf'{$type.IsEquivalentTo($type)};'IsSubclassNull'{$type.IsSubclassOf($null)};'IsSubclassSelf'{$type.IsSubclassOf($type)};'IsSubclassObject'{$type.IsSubclassOf([object])};'HasSameNull'{$type.HasSameMetadataDefinitionAs($null)};'HasSameSelf'{$type.HasSameMetadataDefinitionAs($type)};'MakeGenericNull'{$type.MakeGenericType($null)};'MakeGenericEmpty'{$type.MakeGenericType([type[]]@())};'GetDefaultMembers'{$type.GetDefaultMembers()};'GetMethods'{$type.GetMethods($flags)};'GetMembers'{$type.GetMembers($flags)};'GetMethodNull'{$argsForCall=[object[]]::new(1);$null=[Type].GetMethod('GetMethod',[type[]]@([string])).Invoke($type,$argsForCall)};'GetMethodText'{$type.GetMethod('x')};'GetMemberNull'{$argsForCall=[object[]]::new(1);$null=[Type].GetMethod('GetMember',[type[]]@([string])).Invoke($type,$argsForCall)};'GetMemberText'{$type.GetMember('x')};'GetNestedTypeNull'{$argsForCall=[object[]]::new(1);$null=[Type].GetMethod('GetNestedType',[type[]]@([string])).Invoke($type,$argsForCall)};'GetNestedTypeText'{$type.GetNestedType('x')};'GetInterfaceNull'{$argsForCall=[object[]]::new(1);$null=[Type].GetMethod('GetInterface',[type[]]@([string])).Invoke($type,$argsForCall)};'GetInterfaceText'{$type.GetInterface('x')};'GetEnumNames'{$type.GetEnumNames()};'GetEnumValues'{$type.GetEnumValues()};'GetEnumUnderlyingType'{$type.GetEnumUnderlyingType()};'GetEnumNameNull'{$type.GetEnumName($null)};'IsEnumDefinedNull'{$type.IsEnumDefined($null)}}};$value=Value $result $type;if($op -eq 'P:GenericTypeArguments'){$value=Value ([Type].GetProperty('GenericTypeArguments').GetValue($type)) $type}elseif($op -in @('GetGenericArguments','GetOptionalCustomModifiers','GetRequiredCustomModifiers')){$value=Value ([Type].GetMethod($op,[type[]]@()).Invoke($type,[object[]]@())) $type}}catch{$errorValue=$_.Exception;while($errorValue -is [Reflection.TargetInvocationException] -or $errorValue -is [Management.Automation.MethodInvocationException]){$errorValue=$errorValue.InnerException};$errorName=$errorValue.GetType().FullName;$message=$errorValue.Message;$hResult=$errorValue.HResult;if($errorValue -is [ArgumentException]){$param=$errorValue.ParamName}};$rows.Add([ordered]@{id=$case.id;position=[int]$position;operation=$op;valueUnits=(Units $value);exception=$errorName;messageUnits=(Units $message);hResult=$hResult;paramUnits=(Units $param)})}}
$record=[ordered]@{schemaVersion=1;runtimeVersion=[Environment]::Version.ToString();coreLibSha256=$coreHash;oracleSha256=(Get-FileHash -LiteralPath $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant();planSha256=(Get-FileHash -LiteralPath $PlanPath -Algorithm SHA256).Hash.ToLowerInvariant();constructors=$constructors.ToArray();rows=$rows.ToArray();qualification=$plan.qualification};[IO.File]::WriteAllText($OutputPath,($record|ConvertTo-Json -Depth 14 -Compress)+"`n",[Text.UTF8Encoding]::new($false));Write-Output "PASS signature parameter capture: $($constructors.Count) constructors and $($rows.Count) operations"
